head.script:
// 가이드 : 소수 데이터 정수 표시 샘플 (합성 화면 — 원본 없음)

/*
 * 화면 동작
 * 1. 같은 DataMap 키(dma_num.amt)에 묶인 입력란 10개가 같은 소수 값을 각자의 displayFormat 으로 표시한다
 * 2. 「값 설정」 버튼으로 대표 값(1234.4 / 1234.5 / 1234.01 / -1234.5 / 1234.5678 / 123456789.123)을 넣어
 *    반올림·올림·버림 차이와 float maxLength="9.3" 소수 자리 버림 표시를 비교한다
 * 2-1. float maxLength="9.3" 입력란은 정수 9자리·소수 3자리를 넘는 키 입력을 막는다(서버에서 받은 초과 값은 자르지 않는다)
 * 3. 입력란에 포커스를 주면 원본(소수 포함) 값이 보이고, 수정 후 포커스를 빼면 다시 정수로 표시된다
 * 4. 그리드도 같은 비교를 컬럼별로 보여주며, 어느 컬럼을 편집해도 행의 다른 컬럼에 같은 원본 값이 복사된다
 * 5. 「getValue 확인」 으로 표시값과 무관하게 컴포넌트·DataMap·DataList 에 원본 소수 값이 남아 있음을 확인한다
 * 6. [잘림 재현] 두 번째 그리드는 maxLength 를 넘는 기존 데이터를 담는다. 셀을 편집 모드로 열었다가 값을 바꾸지 않고
 *    나오기만 해도 편집기 validator 가 자른 값이 dataList 에 기록된다. 「변경 확인」 으로 원본 대비 바뀐 셀을 표시한다
 *
 * 담긴 패턴 — 엔진 실측(websquare-engine.js) 결과
 * - dataType="number" + displayFormat="#,###[round|ceil|floor]" : 정수부만 표시, 예약어로 처리 방식 선택(생략 시 [round])
 * - dataType="float"  + displayFormat="#,###"                  : 예약어 무시, 항상 버림 표시(floatFormatter 가 정수부만 잘라 포맷)
 * - input 은 applyFormat="display" 필수 — "all" 이면 표시값↔원본 매핑이 안 남아 getValue 가 소수를 잃을 수 있다
 * - 정수만 표시하는 float input/컬럼에 소수 자릿수 maxLength("13.2" 등)를 주면 소수가 다시 표시된다 → 지정하지 않는다
 * - float + maxLength="9.3" + displayFormat="#,###.###[floor]" : 정수 9·소수 3자리 입력 제한 + 소수 셋째 자리까지 버림 표시
 *   · displayFormat 에 소수가 있으면 예약어가 float 에도 적용된다(formatCurrency 경로) — 표시 자릿수는 maxLength 가 아니라 displayFormat 이 정한다
 *   · 입력 자릿수(maxLength 소수 3)와 표시 자릿수를 맞춘다. "#,###.##[floor]" 이면 1234.567 입력이 1,234.56 으로 보인다(저장값은 1234.567)
 *   · 쉼표 묶음은 쉼표 뒤 # 개수다. "#,##.##" 는 두 자리마다 쉼표(12,34.56) → 반드시 "#,###"
 *   · 자릿수 고정 표시(1,234.50)가 필요하면 # 대신 0 : "#,##0.000[floor]"
 * - [결함 재현] float + maxLength="9.3" + displayFormat="#,###[floor]" : 버림 미적용, 원본 소수 그대로 표시(1234.5678 → 1,234.5678)
 *   · floatFormatter 는 패턴에 소수점이 없으면 정수부만 포맷한 뒤, maxLength 소수 자리가 0 초과("9.3"·"*.*")면 원본 소수부를 다시 붙인다
 *   · number + maxLength="9.3" 은 대안이 아니다 — number 의 maxLength 는 parseInt("9.3") = 소수점 포함 전체 9글자 제한
 * - [A안] float + maxLength="9.3" + displayFormatter="scwin.fmtIntFloor" : 정수 9·소수 3자리 입력 제한 + 정수 버림 표시
 *   · displayFormatter 는 formatterAdapter 로 생성되지만 기본 format() 을 거쳐 표시값↔원본 매핑이 남는다 → getValue 는 원본 소수
 *   · 버림은 Math.trunc(0 방향) — $c.num.floor(Math.floor)는 음수가 -1234.5 → -1235 로 엔진 [floor] 와 다르다
 *   · 저장 시점 검증으로 충분하면 B안 : number + "#,###[floor]" + validateDataCollect { num:"f", maxLengthF:"9.3" } (키 입력 제한 없음)
 * - gridView 는 셀 편집기가 포맷 없이 원본 값을 편집·저장한다 → 컬럼 applyFormat 은 지정하지 않는다
 * - [잘림 재현] 편집 가능한 그리드 컬럼의 maxLength 는 한도를 넘는 기존 데이터를 편집 종료 시 잘라 기록한다
 *   · 편집 종료(handleBlurEventBasic)가 c = validator.validateString(getValue()) 후 변경 비교 없이 __setCellData(c)
 *   · number : maxLength 는 parseInt — "9"·"9.3" 모두 소수점·부호 포함 전체 9글자. 123456789.123 → 123456789 / 1234567890 → 123456789 / -123456789 → -12345678
 *   · number + useMaxLength="true" : 부호 제외·쉼표 무시로 센다(-123456789 유지). 글자 수는 서버 데이터 최대 길이 이상으로 준다(정수 9·소수 3 → "14")
 *   · float : maxFloatLengthCommand 가 정수·소수 자리별로 자른다. 123456789.1234 → 123456789.123 / 1234567890 → 123456789 (A안 컬럼도 같은 위험)
 *   · 일반 input(applyFormat="display")은 바인딩·블러 때 validateString 을 타지 않아 기존 값을 자르지 않는다 — 그리드 편집 경로만의 문제
 *   · 권장 : 편집 컬럼의 정수.소수 자리 검사는 저장 시 validateDataCollect { num:"f", maxLengthF:"9.3" }, 읽기 전용 컬럼은 영향 없음
 *
 * 예약어 주의(엔진 동작)
 * - [ceil] 은 잘리는 첫째 소수 자리만 본다 : 1234.01 → 1,234 (정확한 올림이 필요하면 displayFormatter 로 Math.ceil)
 * - 음수는 절대값 기준 : [floor] -1234.5 → -1,234 / [round] -1234.5 → -1,235
 * - 표시만 바뀐다. 서버에 정수를 보내야 하면 저장 직전에 $c.num.round/floor/ceil 로 명시 변환한다
 */

///////// 1. 변수 및 선언 영역 /////////

// 그리드 비교 컬럼 — 한 컬럼을 편집하면 같은 행의 나머지 컬럼에 같은 원본 값을 복사한다
scwin.GRID_COLS = ["org", "flt", "rnd", "cel", "flr", "f93", "f93i", "f93a"];

// 그리드 초기 데이터 — 반올림·올림·버림 경계 값 + 소수 4자리 이상·maxLength 9.3 한도 값
scwin.GRID_SAMPLE = [1234.4, 1234.5, 1234.56, 1234.01, 1234.09, -1234.5, 1234.999, 1234.5678, 123456789.123];

// 잘림 재현 그리드 — 편집 후 원본(org)과 비교할 컬럼
scwin.CUT_COLS = ["n9", "n93", "n14", "f93"];

// 잘림 재현 데이터 — 서버에서 maxLength 를 넘는 값이 내려온 상황
scwin.CUT_SAMPLE = [123456789.123, 1234567890, -123456789, 12345.6789, 123456789.1234];

///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 10. 21
 * @description 페이지 로드. 입력란 기본 값과 그리드 비교 데이터를 설정한다.
 * @hidden N
*/
scwin.onpageload = function () {
    try {
        scwin.initGrid();
        scwin.initCutGrid();
        scwin.setAmt(1234.56);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "SMPFMT10000.onpageload" });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////

// ── 값 설정 버튼 (thin — 값만 넘긴다) ──
scwin.btn_set1_onclick = function () {
    try {
        scwin.setAmt(1234.4);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "SMPFMT10000.btn_set1_onclick" });
    }
};
scwin.btn_set2_onclick = function () {
    try {
        scwin.setAmt(1234.5);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "SMPFMT10000.btn_set2_onclick" });
    }
};
scwin.btn_set3_onclick = function () {
    try {
        scwin.setAmt(1234.01);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "SMPFMT10000.btn_set3_onclick" });
    }
};
scwin.btn_set4_onclick = function () {
    try {
        scwin.setAmt(-1234.5);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "SMPFMT10000.btn_set4_onclick" });
    }
};
scwin.btn_set5_onclick = function () {
    try {
        scwin.setAmt(1234.5678);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "SMPFMT10000.btn_set5_onclick" });
    }
};
scwin.btn_set6_onclick = function () {
    try {
        scwin.setAmt(123456789.123);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "SMPFMT10000.btn_set6_onclick" });
    }
};

/**
 * @event
 * @name scwin.btn_check_onclick
 * @description 각 입력란의 getValue() 와 DataMap·DataList 값을 표시해 원본 소수 값이 보존됨을 확인한다.
 * @hidden N
*/
scwin.btn_check_onclick = function () {
    try {
        scwin.showResult();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "SMPFMT10000.btn_check_onclick" });
    }
};

/**
 * @event
 * @name scwin.btn_gridReset_onclick
 * @description 그리드 비교 데이터를 초기 값으로 되돌린다.
 * @hidden N
*/
scwin.btn_gridReset_onclick = function () {
    try {
        scwin.initGrid();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "SMPFMT10000.btn_gridReset_onclick" });
    }
};

/**
 * @event
 * @name scwin.btn_cutCheck_onclick
 * @description [잘림 재현] 원본(org) 대비 값이 바뀐 셀을 표시한다.
 * @hidden N
*/
scwin.btn_cutCheck_onclick = function () {
    try {
        scwin.showCutResult();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "SMPFMT10000.btn_cutCheck_onclick" });
    }
};

/**
 * @event
 * @name scwin.btn_cutReset_onclick
 * @description [잘림 재현] 그리드를 한도 초과 원본 데이터로 되돌린다.
 * @hidden N
*/
scwin.btn_cutReset_onclick = function () {
    try {
        scwin.initCutGrid();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "SMPFMT10000.btn_cutReset_onclick" });
    }
};

/**
 * @event
 * @name scwin.grd_num_onafteredit
 * @description 편집한 셀의 원본 값을 같은 행의 다른 비교 컬럼에 복사한다(편집 후에도 소수가 보존되는지 확인용).
 * @param {Number} rowIndex 편집한 행 인덱스
 * @param {Number} columnIndex 편집한 컬럼 인덱스
 * @hidden N
*/
scwin.grd_num_onafteredit = function (rowIndex, columnIndex) {
    try {
        const value = dlt_num.getCellData(rowIndex, grd_num.getColumnID(columnIndex));
        scwin.GRID_COLS.forEach(function (colId) {
            dlt_num.setCellData(rowIndex, colId, value);
        });
    } catch (ex) {
        $c.exception.handleError(ex, { context : "SMPFMT10000.grd_num_onafteredit" });
    }
};

///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.setAmt
 * @author Inswave
 * @date 2026. 10. 21
 * @description 입력란 비교용 원본 값을 DataMap 에 설정하고 확인 결과를 갱신한다.
 * @param {Number} value 설정할 소수 포함 값
 * @hidden N
*/
scwin.setAmt = function (value) {
    dma_num.set("amt", value);
    scwin.showResult();
};

/**
 * @method
 * @name scwin.showResult
 * @author Inswave
 * @date 2026. 10. 21
 * @description 각 입력란의 getValue() 와 DataMap·DataList(포커스 행) 값을 화면에 표시한다.
 * @hidden N
*/
scwin.showResult = function () {
    const inputs = [
        ["float #,###", ibx_float],
        ["number [round]", ibx_round],
        ["number [ceil]", ibx_ceil],
        ["number [floor]", ibx_floor],
        ["number #,###.##", ibx_dec2],
        ["float 9.3 #,###.###[floor]", ibx_f93],
        ["float 9.3 #,###.##[floor]", ibx_f93d2],
        ["float 9.3 #,###[floor](재현)", ibx_f93int],
        ["float 9.3 displayFormatter(A안)", ibx_f93fmt]
    ];
    const inputText = inputs.map(function (item) {
        return item[0] + " = " + item[1].getValue();
    }).join(" / ");
    spn_inputResult.setValue("input getValue() : " + inputText + "  |  dma_num.amt = " + dma_num.get("amt"));

    const rowIndex = Math.max(grd_num.getFocusedRowIndex(), 0);
    const gridText = scwin.GRID_COLS.map(function (colId) {
        return colId + " = " + dlt_num.getCellData(rowIndex, colId);
    }).join(" / ");
    spn_gridResult.setValue("grid " + (rowIndex + 1) + "행 getCellData() : " + gridText);
};

/**
 * @method
 * @name scwin.initGrid
 * @author Inswave
 * @date 2026. 10. 21
 * @description 그리드 비교 데이터를 구성한다. 행마다 모든 컬럼에 같은 원본 값을 넣는다.
 * @hidden N
*/
scwin.initGrid = function () {
    const rows = scwin.GRID_SAMPLE.map(function (value) {
        const row = {};
        scwin.GRID_COLS.forEach(function (colId) {
            row[colId] = value;
        });
        return row;
    });
    dlt_num.setJSON(rows);
};

/**
 * @method
 * @name scwin.fmtIntFloor
 * @author Inswave
 * @date 2026. 10. 21
 * @description [A안] displayFormatter — 소수부를 버리고(0 방향) 천 단위 쉼표를 붙여 표시한다. displayFormat [floor] 와 같은 결과.
 *              float + maxLength="9.3" 과 함께 쓰면 정수 9·소수 3자리 입력 제한을 유지하면서 정수만 표시한다.
 * @param {String} value 원본 값
 * @returns {String} 표시 문자열 (빈 값은 "", 숫자가 아니면 원본 그대로)
 * @hidden N
 * @example
 * <xf:input dataType="float" maxLength="9.3" applyFormat="display" displayFormatter="scwin.fmtIntFloor"/>
 * scwin.fmtIntFloor("1234.5678"); // "1,234"
 * scwin.fmtIntFloor("-1234.567"); // "-1,234"
*/
scwin.fmtIntFloor = function (value) {
    if (value === "" || value === null || value === undefined) {
        return "";
    }
    const num = Number(value);
    if (isNaN(num)) {
        return value;
    }
    return $c.num.formatMoney(String(Math.trunc(num)));
};

/**
 * @method
 * @name scwin.initCutGrid
 * @author Inswave
 * @date 2026. 10. 21
 * @description [잘림 재현] 원본(org)과 비교 컬럼 전부에 maxLength 를 넘는 같은 값을 넣고 결과 표시를 초기화한다.
 * @hidden N
*/
scwin.initCutGrid = function () {
    const rows = scwin.CUT_SAMPLE.map(function (value) {
        const row = { org : value };
        scwin.CUT_COLS.forEach(function (colId) {
            row[colId] = value;
        });
        return row;
    });
    dlt_cut.setJSON(rows);
    scwin.showCutResult();
};

/**
 * @method
 * @name scwin.showCutResult
 * @author Inswave
 * @date 2026. 10. 21
 * @description [잘림 재현] 행마다 비교 컬럼 값을 원본(org)과 견줘 바뀐 셀 목록을 화면에 표시한다.
 * @hidden N
*/
scwin.showCutResult = function () {
    const changes = [];
    for (let rowIndex = 0; rowIndex < dlt_cut.getRowCount(); rowIndex++) {
        const org = dlt_cut.getCellData(rowIndex, "org");
        scwin.CUT_COLS.forEach(function (colId) {
            const value = dlt_cut.getCellData(rowIndex, colId);
            if (Number(value) !== Number(org)) {
                changes.push((rowIndex + 1) + "행 " + colId + " : " + org + " → " + value);
            }
        });
    }
    spn_cutResult.setValue(changes.length === 0
        ? "변경 없음 — 비교 컬럼 셀을 편집 모드로 열었다가 값을 바꾸지 않고 다른 셀로 나온 뒤 「변경 확인」 을 누르세요."
        : "잘린 셀 " + changes.length + "건 : " + changes.join(" / "));
};
